"""Eight months of clean AP history, generated by code (no LLM calls)."""
from __future__ import annotations

import datetime as dt
import random

from company import DEPARTMENTS, ENTITIES, GROUPS, ITEMS, VendorSpec
from probation.models import (
    BankAccountRecord, Company, InvoiceLine, PaymentEntry, POLine, PurchaseInvoice,
    PurchaseOrder, PurchaseReceipt, ReceiptLine, Supplier,
)
from probation.ports.sqlite import EXPENSE_BY_GROUP, SqliteRecord

START = dt.date(2026, 3, 1)
TODAY = dt.date(2026, 10, 24)
INVOICES_PER_MONTH = 1200
TAXED_GROUPS = {"Packaging", "Facilities", "IT & Software", "Fuel & Fleet"}
TAX_RATE_BP = 825  # 8.25%, a generic sales tax rate


GROUP_CODE = {"Produce": "PRD", "Dairy": "DRY", "Meat & Seafood": "MSF", "Dry Goods": "DGS", "Beverage": "BEV",
              "Packaging": "PKG", "Fuel & Fleet": "FLT", "Facilities": "FAC", "Logistics": "LOG",
              "Professional Services": "PRO", "Utilities": "UTL", "IT & Software": "ITS"}


def item_code(group: str, i: int) -> str:
    return f"{GROUP_CODE[group]}-{i + 1:03d}"


def bill_formatter(rng: random.Random, v: VendorSpec):
    abbr = "".join(w[0] for w in v.name.split() if w[0].isalpha()).upper()[:3]
    start = rng.randint(1000, 60000)
    style = rng.randrange(4)
    state = {"n": start}

    def nxt() -> str:
        state["n"] += rng.randint(1, 3)
        n = state["n"]
        return [f"INV-{n}", f"{abbr}-{n}", f"{n}", f"{abbr}26-{n:05d}"][style]

    return nxt


class Counters:
    def __init__(self):
        self.po = 10000
        self.pr = 10000
        self.pi = 100000
        self.pay = 100000
        self.sba = 0

    def next(self, kind: str) -> str:
        setattr(self, kind, getattr(self, kind) + 1)
        n = getattr(self, kind)
        return {"po": f"PO-{n}", "pr": f"PR-{n}", "pi": f"PINV-{n}", "pay": f"PAY-{n}", "sba": f"SBA-{n:05d}"}[kind]


def seed_static(rec: SqliteRecord, vendors: list[VendorSpec], rng: random.Random, ctr: Counters) -> None:
    for code, cname, bank in ENTITIES:
        rec.seed_company(Company(name=code, company_name=cname, bank_account=bank,
                                 ap_account=f"2100 Accounts Payable - {code}", bank_gl_account=f"1010 Operating Bank - {code}"))
        rec.seed_account(f"2100 Accounts Payable - {code}", code, "Liability", "Payable")
        rec.seed_account(f"1010 Operating Bank - {code}", code, "Asset", "Bank")
        rec.seed_account(f"1400 Recoverable Tax - {code}", code, "Asset", "Tax")
        for acct in set(EXPENSE_BY_GROUP.values()) | {"6900 Other Expense"}:
            root = "Liability" if acct.startswith("2") else "Expense"
            rec.seed_account(f"{acct} - {code}", code, root, "Expense")
    for group, items in ITEMS.items():
        for i, (nm, uom, rate) in enumerate(items):
            rec.seed_item(item_code(group, i), nm, group, uom, rate)
    for v in vendors:
        # a few vendors legitimately changed banks during the history window, confirmed by phone
        if v.represents_company is None and rng.random() < 0.04:
            when = (START + dt.timedelta(days=rng.randint(20, 200))).isoformat()
            v.bank[0]["valid_to"] = when
            v.bank.append(dict(bank_name=rng.choice(["Cascade Federal", "Northshore Trust", "Summit National"]),
                               routing_last4=f"{rng.randint(0, 9999):04d}", account_last4=f"{rng.randint(0, 9999):04d}",
                               valid_from=when, source="phone_verified", verified_by="Marisol Vega", verified_at=when))
        rec.seed_supplier(Supplier(name=v.sid, supplier_name=v.name, supplier_group=v.group if not v.represents_company else "Intercompany",
                                   tax_id=v.tax_id, email_domain=v.domain, phone=v.phone, created_at=v.created_at,
                                   represents_company=v.represents_company))
        for b in v.bank:
            name = ctr.next("sba")
            b["sba"] = name
            rec._insert("supplier_bank_account", BankAccountRecord(name=name, supplier=v.sid, valid_to=b.get("valid_to"),
                        **{k: b[k] for k in ("bank_name", "routing_last4", "account_last4", "valid_from", "source",
                                             "verified_by", "verified_at")}).model_dump())


def make_lines(rng: random.Random, v: VendorSpec, drift: bool = True) -> list[POLine]:
    group = v.group
    items = ITEMS[group]
    n_lines = 1 if group in ("Utilities", "Professional Services", "IT & Software") else rng.randint(1, min(4, len(items)))
    picks = rng.sample(range(len(items)), n_lines)
    spend = GROUPS[group]["spend"]
    out = []
    for i in picks:
        nm, uom, rate = items[i]
        if rate >= 100000:
            qty = 1
        elif uom == "hour":
            qty = rng.randint(3, 24)
        elif uom == "gal":
            qty = rng.randint(150, 900)
        else:
            qty = max(1, int(rng.randint(4, 36) * spend))
        r = int(rate * (1 + (rng.uniform(-0.02, 0.02) if drift else 0)))
        if rate >= 100000:
            r = int(rate * rng.uniform(0.85, 1.2))
        out.append(POLine(item_code=item_code(group, i), description=nm, qty=qty, rate_cents=r, amount_cents=qty * r))
    return out


def tax_for(group: str, net: int) -> int:
    return (net * TAX_RATE_BP + 5000) // 10000 if group in TAXED_GROUPS else 0


def bank_on(v: VendorSpec, day: str) -> dict:
    cur = v.bank[0]
    for b in v.bank:
        if b["valid_from"] <= day:
            cur = b
    return cur


def generate_history(rec: SqliteRecord, vendors: list[VendorSpec], rng: random.Random, ctr: Counters) -> dict:
    regular = [v for v in vendors if v.represents_company is None]
    freq = {g: sum(GROUPS[g]["per_month"]) / 2 for g in GROUPS}
    from company import FOOD_GROUPS, NONFOOD_WEIGHT
    # Mission Linen (demo near-duplicate) keeps its frequency so it has recent paid bills to be duplicated
    weights = [v.weight * freq[v.group] * (1 if v.group in FOOD_GROUPS or v.name == "Mission Linen Co." else NONFOOD_WEIGHT)
               for v in regular]
    fmt = {v.sid: bill_formatter(rng, v) for v in vendors}
    stats = {"invoices": 0, "payments": 0, "pos": 0}
    day = START
    days = (TODAY - START).days
    per_day = INVOICES_PER_MONTH * 12 / 365
    while day < TODAY - dt.timedelta(days=1):
        n_today = max(0, int(rng.gauss(per_day * (0.4 if day.weekday() >= 5 else 1.25), 6)))
        for _ in range(n_today):
            v = rng.choices(regular, weights)[0]
            _one_invoice(rec, v, day, rng, ctr, fmt[v.sid], stats)
        # intercompany: monthly storage recharge from cold chain to distributor
        if day.day == 1:
            for v in vendors:
                if v.represents_company:
                    _one_invoice(rec, v, day, rng, ctr, fmt[v.sid], stats)
        day += dt.timedelta(days=1)
    stats["days"] = days
    return {"stats": stats, "formatters": fmt}


def _one_invoice(rec, v: VendorSpec, day: dt.date, rng, ctr, nxt_bill, stats) -> None:
    lines = make_lines(rng, v) if not v.represents_company else [
        POLine(item_code="LOG-003", description="Cold storage and haulage recharge", qty=1,
               rate_cents=rng.randint(1800000, 4200000), amount_cents=0)]
    for ln in lines:
        ln.amount_cents = ln.qty * ln.rate_cents
    net = sum(ln.amount_cents for ln in lines)
    tax = tax_for(v.group, net)
    entity = v.entity
    po_name = None
    if GROUPS.get(v.group, {}).get("po") and not v.represents_company:
        po_name = ctr.next("po")
        dept, who = DEPARTMENTS[v.group]
        po_day = day - dt.timedelta(days=rng.randint(2, 10))
        rec.seed_po(PurchaseOrder(name=po_name, supplier=v.sid, company=entity, transaction_date=po_day.isoformat(),
                                  department=dept, requested_by=who, grand_total_cents=net + tax, status="completed",
                                  items=lines))
        rec.seed_receipt(PurchaseReceipt(name=ctr.next("pr"), supplier=v.sid, company=entity,
                                         posting_date=(day - dt.timedelta(days=rng.randint(0, 2))).isoformat(),
                                         purchase_order=po_name,
                                         items=[ReceiptLine(item_code=l.item_code, received_qty=l.qty) for l in lines]))
        stats["pos"] += 1
    pi = PurchaseInvoice(name=ctr.next("pi"), supplier=v.sid, company=entity, bill_no=nxt_bill(), bill_date=day.isoformat(),
                         posting_date=(day + dt.timedelta(days=rng.randint(0, 2))).isoformat(), purchase_order=po_name,
                         net_total_cents=net, tax_cents=tax, grand_total_cents=net + tax, source_doc="history",
                         items=[InvoiceLine(**l.model_dump()) for l in lines])
    rec.post_purchase_invoice(pi, commit=False)
    stats["invoices"] += 1
    due = day + dt.timedelta(days=30 if v.group not in ("Utilities",) else 15)
    if due <= TODAY - dt.timedelta(days=1):
        pay_day = due - dt.timedelta(days=rng.randint(0, 3))
        b = bank_on(v, pay_day.isoformat())
        rec.post_payment_entry(PaymentEntry(name=ctr.next("pay"), company=entity, party=v.sid,
                                            paid_amount_cents=pi.grand_total_cents, posting_date=pay_day.isoformat(),
                                            reference_invoice=pi.name, bank_account=b["sba"],
                                            transfer_id=f"ach_hist_{ctr.pay}"), commit=False)
        stats["payments"] += 1
